__device__ __forceinline__ void cp_async_wait1() { asm volatile("cp.async.wait_group 1;\n" ::); }
__device__ __forceinline__ void cp_async_wait0() { asm volatile("cp.async.wait_group 0;\n" ::); }
__global__ void matmul_partial_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ P,
    const int M,
    const int N,
    const int K,
    const int k_tiles_total,
    const int tiles_per_split) {
    extern __shared__ float smem[];
    float* As = smem;
    float* Bs = smem + STAGES * BM * ABK;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int nthreads = blockDim.x * blockDim.y;
    const int tid = ty * blockDim.x + tx;
    const int m0 = blockIdx.y * BM;
    const int n0 = blockIdx.x * BN;
    const int split = blockIdx.z;
    const int k_tile_begin = split * tiles_per_split;
    int k_tile_end = k_tile_begin + tiles_per_split;
    if (k_tile_end > k_tiles_total) k_tile_end = k_tiles_total;
    const int a_chunks = (BM * BK) / 4;
    const int b_chunks = (BK * BN) / 4;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;
    }
    auto load_tile = [&](int buf, int kt) {
        const int k0 = kt * BK;
        constexpr int A_VECS_PER_ROW = BK / 4;
        constexpr int B_VECS_PER_ROW = BN / 4;
        #pragma unroll
        for (int c = tid; c < a_chunks; c += nthreads) {
            const int row = c / A_VECS_PER_ROW;
            const int col = (c % A_VECS_PER_ROW) * 4;
            const int m_load = m0 + row;
            const int k = k0 + col;
            const float* src = A + static_cast<long long>(m_load) * K + k;
            float* dst = &As[(buf * BM + row) * ABK + col];
            int bytes = 0;
            if (m_load < M) {
                bytes = (K - k) * 4;
                if (bytes < 0) bytes = 0;
                if (bytes > 16) bytes = 16;
            }
            if (bytes > 0 && ((reinterpret_cast<uintptr_t>(src) & 15) == 0)) {
                cp_async16(dst, src, bytes);
            } else if (bytes == 0) {
                dst[0] = 0.0f; dst[1] = 0.0f; dst[2] = 0.0f; dst[3] = 0.0f;
            } else {
                float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
                if (k < K) v0 = A[static_cast<long long>(m_load) * K + k];
                if (k + 1 < K) v1 = A[static_cast<long long>(m_load) * K + k + 1];
                if (k + 2 < K) v2 = A[static_cast<long long>(m_load) * K + k + 2];
                if (k + 3 < K) v3 = A[static_cast<long long>(m_load) * K + k + 3];
                dst[0] = v0; dst[1] = v1; dst[2] = v2; dst[3] = v3;
            }
        }
        #pragma unroll
        for (int c = tid; c < b_chunks; c += nthreads) {
            const int row = c / B_VECS_PER_ROW;
            const int col = (c % B_VECS_PER_ROW) * 4;
            const int k = k0 + row;
            const int n_load = n0 + col;
            const float* src = B + static_cast<long long>(k) * N + n_load;
            float* dst = &Bs[(buf * BK + row) * BBNS + col];
            int bytes = 0;
            if (k < K) {
                bytes = (N - n_load) * 4;
                if (bytes < 0) bytes = 0;
                if (bytes > 16) bytes = 16;
            }
            if (bytes > 0 && ((reinterpret_cast<uintptr_t>(src) & 15) == 0)) {
                cp_async16(dst, src, bytes);
            } else if (bytes == 0) {
                dst[0] = 0.0f; dst[1] = 0.0f; dst[2] = 0.0f; dst[3] = 0.0f;
            } else {
                float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
                if (n_load < N) v0 = B[static_cast<long long>(k) * N + n_load];
                if (n_load + 1 < N) v1 = B[static_cast<long long>(k) * N + n_load + 1];
                if (n_load + 2 < N) v2 = B[static_cast<long long>(k) * N + n_load + 2];
                if (n_load + 3 < N) v3 = B[static_cast<long long>(k) * N + n_load + 3];
                dst[0] = v0; dst[1] = v1; dst[2] = v2; dst[3] = v3;
            }
        }
    };
    if (k_tile_begin < k_tile_end) {
        load_tile(0, k_tile_begin);
        cp_async_commit();
    }
    for (int kt = k_tile_begin; kt < k_tile_end; ++kt) {
        const int cur = (kt - k_tile_begin) % STAGES;
        const int pf = kt + STAGES - 1;
        if (pf < k_tile_end) {
            load_tile((pf - k_tile_begin) % STAGES, pf);
            cp_async_commit();
        }
        if (kt + 1 < k_tile_end) cp_async_wait1(); else cp_async_wait0();
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float av[TM];
            float bv[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) av[i] = As[(cur * BM + ty * TM + i) * ABK + kk];
            const float4 b0 = *reinterpret_cast<const float4*>(&Bs[(cur * BK + kk) * BBNS + tx * TN]);
            const float4 b1 = *reinterpret_cast<const float4*>(&Bs[(cur * BK + kk) * BBNS + tx * TN + 4]);
            bv[0] = b0.x; bv[1] = b0.y; bv[2] = b0.z; bv[3] = b0.w;
            bv[4] = b1.x; bv[5] = b1.y; bv[6] = b1.z; bv[7] = b1.w;
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) acc[i][j] += av[i] * bv[j];
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int row = m0 + ty * TM + i;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int col = n0 + tx * TN + j;
            if (row < M && col < N) P[(static_cast<long long>(split) * M + row) * N + col] = acc[i][j];
        }
    }
}
__global__ void splitk_reduce_kernel(
    const float* __restrict__ P,
    float* __restrict__ C,
    const int total,
    const int splits) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total) {
        float sum = 0.0f;
        for (int s = 0; s < splits; ++s) sum += P[static_cast<long long>(s) * total + idx];
        C[idx] = sum;
    }
}
torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda());
    TORCH_CHECK(B.is_cuda());
    TORCH_CHECK(A.scalar_type() == torch::kFloat32);
    TORCH_CHECK(B.scalar_type() == torch::kFloat32);
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2);
    TORCH_CHECK(A.size(1) == B.size(0));
    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    const int M = static_cast<int>(Ac.size(0));
    const int K = static_cast<int>(Ac.size(1));
    const int N = static_cast<int>(Bc.size(1));
    auto C = torch::empty({M, N}, Ac.options());
    const int total = M * N;
    if (total == 0) return C;
    const int k_tiles_total = (K + BK - 1) / BK;
    int device = 0;
    cudaError_t device_err = cudaGetDevice(&device);
    TORCH_CHECK(device_err == cudaSuccess, "cudaGetDevice failed: ", cudaGetErrorString(device_err));
    int num_sms = 0;
    cudaError_t sm_err = cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, device);
    TORCH_CHECK(sm_err == cudaSuccess, "cudaDeviceGetAttribute failed: ", cudaGetErrorString(sm_err));
    const int m_tiles = (M + BM - 1) / BM;
    const int n_tiles = (N + BN - 1) / BN;
    const int out_tiles = m_tiles * n_tiles;
    int target_splits = 1;
    if (out_tiles > 0) target_splits = num_sms > 0 ? (num_sms * 2 + out_tiles - 1) / out_tiles : 8;
    if (target_splits < 1) target_splits = 1;
    if (target_splits > MAX_SPLITS) target_splits = MAX_SPLITS;
    int splits = k_tiles_total < target_splits ? k_tiles_total : target_splits;
    if (splits < 1) splits = 1;
    const int tiles_per_split = (k_tiles_total + splits - 1) / splits;
    const int splits_used = (k_tiles_total + tiles_per_split - 1) / tiles_per_split;
    auto partial = torch::empty({splits_used, M, N}, Ac.options());
    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM, splits_used);
    const size_t shmem_bytes = static_cast<size_t>(STAGES) * (BM * ABK + BK * BBNS) * sizeof(float);
    int max_dynamic_smem = 0;
    cudaError_t prop_err = cudaDeviceGetAttribute(&max_dynamic_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
    TORCH_CHECK(prop_err == cudaSuccess, "cudaDeviceGetAttribute failed: ", cudaGetErrorString(prop_err));
    TORCH_CHECK(shmem_bytes <= static_cast<size_t>(max_dynamic_smem),
                "Kernel requires ", shmem_bytes,
                " bytes of dynamic shared memory, but this device supports only ",
                max_dynamic_smem, " bytes per block.");
