        matmul_partial_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        static_cast<int>(shmem_bytes));
    TORCH_CHECK(attr_err == cudaSuccess,
                "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(attr_err));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_partial_kernel<<<grid, block, shmem_bytes, stream>>>(
        Ac.data_ptr<float>(),
        Bc.data_ptr<float>(),
        partial.data_ptr<float>(),
        M, N, K, k_tiles_total, tiles_per_split);
    cudaError_t partial_err = cudaGetLastError();
    TORCH_CHECK(partial_err == cudaSuccess,
                "matmul_partial_kernel launch failed: ",
                cudaGetErrorString(partial_err));
    dim3 reduce_block(256);
    dim3 reduce_grid((total + 255) / 256);
    splitk_reduce_kernel<<<reduce_grid, reduce_block, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        total, splits_used);
    cudaError_t reduce_err = cudaGetLastError();
    TORCH_CHECK(reduce_err == cudaSuccess,
                "splitk_reduce_kernel launch failed: ",
                cudaGetErrorString(reduce_err));
    return C;
}
